import base64
import gzip
import json
from pathlib import Path
import runpy
import sys
from tempfile import TemporaryDirectory

BUNDLE = ""

if __name__ == "__main__":
    with TemporaryDirectory(prefix="za-stolom-") as folder:
        root = Path(folder)
        files = json.loads(gzip.decompress(base64.b64decode(BUNDLE)))
        for name, contents in files.items():
            path = root / name
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(base64.b64decode(contents))
        sys.path.insert(0, folder)
        runpy.run_path(str(root / "host_rooms.py"),
                       init_globals={"DEFAULT_REGISTRY": "https://table-room-registry.maksimka-zachem.workers.dev"},
                       run_name="__main__")
